const std=@import("std");
const p=@import("pddl_parser.zig");
const g=@import("grounding.zig");
const search=@import("search.zig");
const Element=struct { action:?usize,noop:?usize=null,pre:g.Set,add:g.Set,del:g.Set };
const Level=struct { facts:g.Set,mutex:[]g.Set,elements:[]const Element=&.{},action_mutex:[]u512=&.{} };
const Memo=struct { level:usize,goals:g.Set };
pub const Result=struct { search:search.Result,layers:[]const []const usize=&.{},memo_hits:usize=0 };
fn actionBit(i:usize) u512 { return @as(u512,1)<<@intCast(i); }
fn compatible(set:g.Set,mutex:[]const g.Set) bool { for(g.members(set)) |q| if(mutex[q]&set!=0) return false; return true; }
fn pairs(mutex:anytype) usize { var count:usize=0; for(mutex) |row| count+=@popCount(row); return count/2; }
const Extractor=struct {
    levels:*std.ArrayList(Level),memo:std.AutoHashMap(Memo,void),searched:usize=0,hits:usize=0,tried:usize=0,
    fn extract(self:*Extractor,level:usize,goals:g.Set) ?[]const []const usize {
        if(level==0) return &.{}; const key=Memo{.level=level,.goals=goals}; if(self.memo.contains(key)) { self.hits+=1; return null; } self.searched+=1;
        const result=self.assign(level,g.members(goals),0,&.{}); if(result==null) self.memo.put(key,{}) catch @panic("allocation failed"); return result;
    }
    fn assign(self:*Extractor,level:usize,goals:[]const usize,start:usize,chosen:[]const usize) ?[]const []const usize {
        const previous=self.levels.items[level-1]; var covered:g.Set=0; for(chosen) |e| covered|=previous.elements[e].add; var at=start; while(at<goals.len and covered&g.bit(goals[at])!=0) at+=1;
        if(at==goals.len) { var pre:g.Set=0; for(chosen) |e| pre|=previous.elements[e].pre; const earlier=self.extract(level-1,pre) orelse return null; var actions:std.ArrayList(usize)=.empty; for(chosen) |e| if(previous.elements[e].action) |a| p.append(usize,&actions,a); std.mem.sort(usize,actions.items,{},std.sort.asc(usize)); const result=p.alloc([]const usize,earlier.len+1); @memcpy(result[0..earlier.len],earlier); result[earlier.len]=actions.items; return result; }
        const fact=goals[at]; var achievers:std.ArrayList(usize)=.empty;
        for(previous.elements,0..) |element,i| if(element.noop!=null and element.noop.?==fact) p.append(usize,&achievers,i);
        for(previous.elements,0..) |element,i| if(element.action!=null and element.add&g.bit(fact)!=0) p.append(usize,&achievers,i);
        for(achievers.items) |e| { var ok=true; for(chosen) |other| if(previous.action_mutex[e]&actionBit(other)!=0) { ok=false; break; }; if(!ok) continue; self.tried+=1; const next=p.alloc(usize,chosen.len+1); @memcpy(next[0..chosen.len],chosen); next[chosen.len]=e; if(self.assign(level,goals,at+1,next)) |result| return result; }
        return null;
    }
};
pub fn run(ground:g.Ground,limit:usize,text:*p.Text) Result {
    var negative:g.Set=0; for(ground.actions) |action| negative|=action.neg; const complements=g.members(negative); const total=ground.facts.len+complements.len; const complement=p.alloc(?usize,ground.facts.len); @memset(complement,null); for(complements,0..) |fact,i| complement[fact]=ground.facts.len+i;
    var initial=ground.initial; for(complements) |fact| if(initial&g.bit(fact)==0) { initial|=g.bit(complement[fact].?); };
    const transformed=p.alloc(Element,ground.actions.len); for(ground.actions,transformed,0..) |action,*element,i| { element.*=.{.action=i,.pre=action.pre,.add=action.add,.del=action.del}; for(g.members(action.neg)) |fact| element.pre|=g.bit(complement[fact].?); for(complements) |fact| { if(action.del&g.bit(fact)!=0) element.add|=g.bit(complement[fact].?); if(action.add&g.bit(fact)!=0) element.del|=g.bit(complement[fact].?); } }
    text.line("complementary facts: {d}",.{complements.len}); var levels:std.ArrayList(Level)=.empty; const mutex=p.alloc(g.Set,total); @memset(mutex,0); p.append(Level,&levels,.{.facts=initial,.mutex=mutex}); var extractor=Extractor{.levels=&levels,.memo=std.AutoHashMap(Memo,void).init(p.allocator)}; var result=Result{.search=.{.status="level limit"}};
    for(0..limit+1) |level| {
        const current=levels.items[level]; text.line("fact level {d}: facts={d} mutexes={d}",.{level,@popCount(current.facts),pairs(current.mutex)}); var extracted=false;
        if(g.subset(ground.goal,current.facts) and compatible(ground.goal,current.mutex)) { extracted=true; const old_search=extractor.searched; const old_hits=extractor.hits; const plan=extractor.extract(level,ground.goal); text.line("extract level {d}: {s} searched={d} memo_hits={d}",.{level,if(plan!=null) "success" else "fail",extractor.searched-old_search,extractor.hits-old_hits}); if(plan) |layers| { result.layers=layers; result.search.status="solved"; break; } }
        if(!extracted and level>0 and @popCount(current.facts)==@popCount(levels.items[level-1].facts) and pairs(current.mutex)==pairs(levels.items[level-1].mutex)) { result.search.status="unreachable"; break; }
        if(level==limit) break;
        var elements:std.ArrayList(Element)=.empty; for(transformed) |element| if(g.subset(element.pre,current.facts) and compatible(element.pre,current.mutex)) p.append(Element,&elements,element); const actions=elements.items.len;
        for(g.members(current.facts)) |fact| p.append(Element,&elements,.{.action=null,.noop=fact,.pre=g.bit(fact),.add=g.bit(fact),.del=0});
        const action_mutex=p.alloc(u512,elements.items.len); @memset(action_mutex,0);
        for(elements.items,0..) |x,i| for(elements.items[i+1..],i+1..) |y,j| {
            var exclusive=(x.del&(y.pre|y.add)!=0) or (y.del&(x.pre|x.add)!=0); for(g.members(x.pre)) |fact| if(current.mutex[fact]&y.pre!=0) { exclusive=true; break; };
            if(exclusive) { action_mutex[i]|=actionBit(j); action_mutex[j]|=actionBit(i); }
        };
        levels.items[level].elements=elements.items; levels.items[level].action_mutex=action_mutex; text.line("action level {d}: actions={d} noops={d} mutexes={d}",.{level,actions,@popCount(current.facts),pairs(action_mutex)});
        var facts:g.Set=0; for(elements.items) |element| facts|=element.add; const next_mutex=p.alloc(g.Set,total); @memset(next_mutex,0); const members=g.members(facts);
        for(members,0..) |q,i| for(members[i+1..]) |r| { var exclusive=true; outer: for(elements.items,0..) |x,xi| { if(x.add&g.bit(q)==0) continue; for(elements.items,0..) |y,yi| if(y.add&g.bit(r)!=0 and (xi==yi or action_mutex[xi]&actionBit(yi)==0)) { exclusive=false; break :outer; }; } if(exclusive) { next_mutex[q]|=g.bit(r); next_mutex[r]|=g.bit(q); } };
        p.append(Level,&levels,.{.facts=facts,.mutex=next_mutex});
    }
    result.search.expanded=extractor.searched; result.search.generated=extractor.tried; result.memo_hits=extractor.hits;
    var plan:std.ArrayList(usize)=.empty; for(result.layers) |layer| for(layer) |action| { p.append(usize,&plan,action); }; result.search.plan=plan.items;
    if(p.eq(result.search.status,"solved")) { text.line("result: solved levels={d} length={d} cost={d} searched={d} memo_hits={d} tried={d}",.{result.layers.len,plan.items.len,search.cost(ground,plan.items),extractor.searched,extractor.hits,extractor.tried}); for(result.layers,1..) |layer,i| { text.put("layer {d}:",.{i}); if(layer.len==0) text.put(" -",.{}); for(layer) |action| text.put(" {s}",.{ground.actions[action].notation}); text.put("\n",.{}); } }
    else text.line("result: FAIL ({s}) searched={d} memo_hits={d} tried={d}",.{result.search.status,extractor.searched,extractor.hits,extractor.tried}); return result;
}

const std=@import("std");
const p=@import("pddl_parser.zig");
pub const Set=u256;
pub fn bit(i:usize) Set { return @as(Set,1)<<@intCast(i); }
pub fn subset(a:Set,b:Set) bool { return a&b==a; }
pub fn members(s:Set) []const usize { var list:std.ArrayList(usize)=.empty; for(0..256) |i| if(s&bit(i)!=0) p.append(usize,&list,i); return list.items; }
pub fn subtype(domain:p.Domain,child:[]const u8,parent:[]const u8) bool { var t=child; while(true) { if(p.eq(t,parent)) return true; if(p.eq(t,"object")) return false; t=domain.types[p.find(domain.types,t) orelse return false].parent; } }
pub fn fluent(domain:p.Domain,predicate:[]const u8) bool { return domain.predicates[p.find(domain.predicates,predicate).?].fluent; }
pub const Action=struct { source:usize,args:[]const []const u8,cost:i64,notation:[]const u8,pre:Set=0,neg:Set=0,add:Set=0,del:Set=0 };
pub const Counts=struct { assignments:usize=0,candidates:usize=0,reachable:usize=0 };
pub const Ground=struct { facts:[]const p.Atom,actions:[]const Action,initial:Set,goal:Set,unreachable:[]const p.Atom,counts:[]Counts,static_count:usize };
const Candidate=struct { source:usize,args:[]const []const u8,pre:[]const p.Atom,neg:[]const p.Atom,add:[]const p.Atom,del:[]const p.Atom,reachable:bool=false };
fn unique(list:*std.ArrayList(p.Atom),a:p.Atom) void { if(p.atomIndex(list.items,a)==null) p.append(p.Atom,list,a); }
fn enumerate(domain:p.Domain,problem:p.Problem,schema:usize,depth:usize,args:[][]const u8,counts:*Counts,out:*std.ArrayList(Candidate)) void {
    const action=domain.actions[schema]; if(depth<args.len) { for(problem.objects) |object| if(subtype(domain,object.typ,action.parameters[depth].typ)) { args[depth]=object.name; enumerate(domain,problem,schema,depth+1,args,counts,out); }; return; }
    counts.assignments+=1; var pre:std.ArrayList(p.Atom)=.empty; var neg:std.ArrayList(p.Atom)=.empty; var adds:std.ArrayList(p.Atom)=.empty; var deletes:std.ArrayList(p.Atom)=.empty;
    for(action.conditions) |literal| { const a=p.substitute(literal.atom,action.parameters,args); if(p.eq(a.predicate,"=") or !fluent(domain,a.predicate)) { const truth=if(p.eq(a.predicate,"=")) p.eq(a.terms[0],a.terms[1]) else p.atomIndex(problem.initial,a)!=null; if(truth==literal.negative) return; } else unique(if(literal.negative) &neg else &pre,a); }
    for(action.effects) |literal| unique(if(literal.negative) &deletes else &adds,p.substitute(literal.atom,action.parameters,args));
    const values=p.alloc([]const u8,args.len); @memcpy(values,args); counts.candidates+=1; p.append(Candidate,out,.{.source=schema,.args=values,.pre=pre.items,.neg=neg.items,.add=adds.items,.del=deletes.items});
}
fn atomSet(facts:[]const p.Atom,atoms:[]const p.Atom) Set { var set:Set=0; for(atoms) |a| if(p.atomIndex(facts,a)) |i| { set|=bit(i); }; return set; }
pub fn ground(domain:p.Domain,problem:p.Problem) Ground {
    const counts=p.alloc(Counts,domain.actions.len); @memset(counts,.{}); var candidates:std.ArrayList(Candidate)=.empty; for(domain.actions,0..) |action,i| enumerate(domain,problem,i,0,p.alloc([]const u8,action.parameters.len),&counts[i],&candidates);
    var facts:std.ArrayList(p.Atom)=.empty; var static_count:usize=0; for(problem.initial) |a| { if(fluent(domain,a.predicate)) unique(&facts,a) else static_count+=1; }
    while(true) { var changed=false; for(candidates.items) |*candidate| { if(candidate.reachable) continue; var reachable=true; for(candidate.pre) |a| if(p.atomIndex(facts.items,a)==null) { reachable=false; break; }; if(reachable) { candidate.reachable=true; changed=true; counts[candidate.source].reachable+=1; for(candidate.add) |a| unique(&facts,a); } } if(!changed) break; }
    const Context=struct { domain:p.Domain,problem:p.Problem }; std.mem.sort(p.Atom,facts.items,Context{.domain=domain,.problem=problem},struct { fn less(ctx:Context,a:p.Atom,b:p.Atom) bool { const ap=p.find(ctx.domain.predicates,a.predicate).?; const bp=p.find(ctx.domain.predicates,b.predicate).?; if(ap!=bp) return ap<bp; for(a.terms,b.terms) |x,y| { const xi=p.find(ctx.problem.objects,x).?; const yi=p.find(ctx.problem.objects,y).?; if(xi!=yi) return xi<yi; } return false; } }.less);
    var actions:std.ArrayList(Action)=.empty; for(candidates.items) |candidate| if(candidate.reachable) { const schema=domain.actions[candidate.source]; const add=atomSet(facts.items,candidate.add); p.append(Action,&actions,.{.source=candidate.source,.args=candidate.args,.cost=schema.cost,.notation=(p.Atom{.predicate=schema.name,.terms=candidate.args}).notation(),.pre=atomSet(facts.items,candidate.pre),.neg=atomSet(facts.items,candidate.neg),.add=add,.del=atomSet(facts.items,candidate.del)&~add}); };
    var goal:Set=0; var unreachable:std.ArrayList(p.Atom)=.empty; for(problem.goals) |a| { if(p.atomIndex(facts.items,a)) |i| goal|=bit(i) else if(fluent(domain,a.predicate) or p.atomIndex(problem.initial,a)==null) p.append(p.Atom,&unreachable,a); }
    return .{.facts=facts.items,.actions=actions.items,.initial=atomSet(facts.items,problem.initial),.goal=goal,.unreachable=unreachable.items,.counts=counts,.static_count=static_count};
}

const std=@import("std");
const p=@import("pddl_parser.zig");
const g=@import("grounding.zig");
pub const infinity:i64=1<<60;
pub fn str(v:i64) []const u8 { return if(v>=infinity) "inf" else p.fmt("{d}",.{v}); }
fn add(a:i64,b:i64) i64 { return @min(infinity,a+b); }
pub const Values=struct { goalcount:i64=0,hmax:i64=0,hadd:i64=0,ff:i64=0,lmcount:i64=0,relaxed:[]const usize=&.{},helpful:[]const usize=&.{},landmarks:g.Set=0,
    pub fn get(self:Values,name:[]const u8) i64 { if(p.eq(name,"none")) return 0; if(p.eq(name,"goalcount")) return self.goalcount; if(p.eq(name,"hmax")) return self.hmax; if(p.eq(name,"hadd")) return self.hadd; if(p.eq(name,"ff")) return self.ff; return self.lmcount; }
};
fn relaxedCosts(ground:g.Ground,state:g.Set,sum:bool) []i64 { const costs=p.alloc(i64,ground.facts.len); for(costs,0..) |*cost,i| cost.*=if(state&g.bit(i)!=0) 0 else infinity; while(true) { var changed=false; for(ground.actions) |action| { var v:i64=0; for(g.members(action.pre)) |i| v=if(sum) add(v,costs[i]) else @max(v,costs[i]); v=add(v,action.cost); for(g.members(action.add)) |i| if(v<costs[i]) { costs[i]=v; changed=true; }; } if(!changed) break; } return costs; }
fn achieve(ground:g.Ground,state:g.Set,costs:[]const i64,fact:usize,selected:[]bool) void { if(state&g.bit(fact)!=0) return; var best:?usize=null; var minimum=infinity; for(ground.actions,0..) |action,i| if(action.add&g.bit(fact)!=0) { var value=action.cost; for(g.members(action.pre)) |q| value=add(value,costs[q]); if(value<minimum) { minimum=value; best=i; } }; const a=best.?; if(selected[a]) return; selected[a]=true; for(g.members(ground.actions[a].pre)) |q| achieve(ground,state,costs,q,selected); }
fn compute(ground:g.Ground,state:g.Set,landmarks:bool) Values {
    var out:Values=.{}; out.goalcount=@popCount(ground.goal&~state); const maxcost=relaxedCosts(ground,state,false); const sumcost=relaxedCosts(ground,state,true);
    for(g.members(ground.goal)) |goal| { out.hmax=@max(out.hmax,maxcost[goal]); out.hadd=add(out.hadd,sumcost[goal]); }
    if(out.hadd>=infinity) { out.ff=infinity; out.lmcount=infinity; return out; }
    const selected=p.alloc(bool,ground.actions.len); @memset(selected,false); for(g.members(ground.goal)) |goal| achieve(ground,state,sumcost,goal,selected); var relaxed:std.ArrayList(usize)=.empty; var helpful:std.ArrayList(usize)=.empty;
    for(selected,ground.actions,0..) |yes,action,i| if(yes) { p.append(usize,&relaxed,i); out.ff+=action.cost; if(g.subset(action.pre,state) and action.neg&state==0) p.append(usize,&helpful,i); };
    out.relaxed=relaxed.items; out.helpful=helpful.items; if(!landmarks) return out;
    const factlevel=p.alloc(i64,ground.facts.len); const actionlevel=p.alloc(i64,ground.actions.len); @memset(factlevel,infinity); @memset(actionlevel,infinity); for(g.members(state)) |q| factlevel[q]=0;
    var level:i64=0; while(true) : (level+=1) { var changed=false; for(ground.actions,0..) |action,i| { if(actionlevel[i]!=infinity) continue; var ready=true; for(g.members(action.pre)) |q| if(factlevel[q]>level) { ready=false; break; }; if(ready) { actionlevel[i]=level; for(g.members(action.add)) |q| if(factlevel[q]==infinity) { factlevel[q]=level+1; changed=true; }; } } if(!changed) break; }
    out.landmarks=ground.goal&~state;
    while(true) { var changed=false; for(g.members(out.landmarks)) |fact| {
        var intersection:g.Set=~@as(g.Set,0); for(ground.actions,0..) |action,i| if(action.add&g.bit(fact)!=0 and actionlevel[i]==factlevel[fact]-1) { intersection&=action.pre; };
        for(g.members(intersection&~state&~out.landmarks)) |q| { var reachable=state; while(true) { const old=reachable; for(ground.actions) |action| if(action.add&g.bit(q)==0 and g.subset(action.pre,reachable)) { reachable|=action.add; }; if(reachable==old) break; } if(!g.subset(ground.goal,reachable)) { out.landmarks|=g.bit(q); changed=true; } }
    } if(!changed) break; }
    out.lmcount=@popCount(out.landmarks); return out;
}
pub fn evaluate(ground:g.Ground,state:g.Set) Values { return compute(ground,state,true); }
pub fn helpfulActions(ground:g.Ground,state:g.Set) []const usize { return compute(ground,state,false).helpful; }
pub fn estimate(ground:g.Ground,state:g.Set,name:[]const u8) i64 {
    if(p.eq(name,"none")) return 0; if(p.eq(name,"goalcount")) return @popCount(ground.goal&~state);
    if(p.eq(name,"hmax") or p.eq(name,"hadd")) { const sum=p.eq(name,"hadd"); const costs=relaxedCosts(ground,state,sum); var result:i64=0; for(g.members(ground.goal)) |q| result=if(sum) add(result,costs[q]) else @max(result,costs[q]); return result; }
    return compute(ground,state,p.eq(name,"lmcount")).get(name);
}

const std=@import("std");
const p=@import("pddl_parser.zig");
const g=@import("grounding.zig");
const h=@import("heuristics.zig");
const search=@import("search.zig");
const gp=@import("graphplan.zig");
fn arguments(domain:p.Domain,args:[]const []const u8,expected:[]const p.Typed,table:[]const p.Typed,noun:[]const u8) ?[]const u8 {
    if(args.len!=expected.len) return p.fmt("expected {d} arguments, got {d}",.{expected.len,args.len});
    for(args,expected,1..) |arg,typ,i| { const j=p.find(table,arg) orelse return p.fmt("unknown {s} {s}",.{noun,arg}); if(!g.subtype(domain,table[j].typ,typ.typ)) return p.fmt("argument {d} ({s}) is not of type {s}",.{i,arg,typ.typ}); } return null;
}
fn atomError(domain:p.Domain,atom:p.Atom,table:[]const p.Typed,noun:[]const u8,equality:bool) ?[]const u8 {
    if(equality and p.eq(atom.predicate,"=")) return arguments(domain,atom.terms,&.{.{.name="",.typ="object"},.{.name="",.typ="object"}},table,noun);
    const pred=p.find(domain.predicates,atom.predicate) orelse return p.fmt("unknown predicate {s}",.{atom.predicate}); return arguments(domain,atom.terms,domain.predicates[pred].arguments,table,noun);
}
fn validateDomain(domain:*p.Domain,text:*p.Text) void {
    var kept:std.ArrayList(p.Schema)=.empty; text.line("== domain {s} ==",.{domain.name});
    for(domain.actions) |schema| { var failure:?[]const u8=null; for(schema.parameters) |parameter| if(p.find(domain.types,parameter.typ)==null) { failure=p.fmt("unknown type {s}",.{parameter.typ}); break; };
        if(failure==null) outer: for([_] []const p.Literal{schema.conditions,schema.effects}) |literals| for(literals) |literal| { if(atomError(domain.*,literal.atom,schema.parameters,"variable",true)) |error_message| { failure=p.fmt("{s}: {s}",.{literal.atom.notation(),error_message}); break :outer; } };
        if(failure) |message| text.line("error: action {s}: {s}",.{schema.name,message}) else p.append(p.Schema,&kept,schema);
    }
    domain.actions=kept.items;
    for(domain.predicates) |*predicate| { var used=false; for(domain.actions) |schema| { for(schema.conditions) |literal| if(p.eq(literal.atom.predicate,predicate.name)) { used=true; }; for(schema.effects) |literal| if(p.eq(literal.atom.predicate,predicate.name)) { used=true; predicate.fluent=true; }; } if(!used) text.line("warning: predicate {s} is not used by any action",.{predicate.name}); }
    for(domain.types) |typ| { text.put("type {s}",.{typ.name}); var current=typ.name; while(!p.eq(current,"object")) { current=domain.types[p.find(domain.types,current).?].parent; text.put(" < {s}",.{current}); } text.put("\n",.{}); }
    for(domain.predicates) |predicate| text.line("predicate {s}/{d} {s}",.{predicate.name,predicate.arguments.len,if(predicate.fluent) "fluent" else "static"});
    for(domain.actions) |schema| { var adds:usize=0; var deletes:usize=0; for(schema.effects) |literal| { if(literal.negative) deletes+=1 else adds+=1; } text.line("action {s}/{d} cost={d} pre={d} add={d} del={d}",.{schema.name,schema.parameters.len,schema.cost,schema.conditions.len,adds,deletes}); }
}
fn validateProblem(domain:p.Domain,problem:*p.Problem) void {
    for([_]bool{false,true}) |goal| { var kept:std.ArrayList(p.Atom)=.empty; for(if(goal) problem.goals else problem.initial) |atom| { const failure=atomError(domain,atom,problem.objects,"object",false) orelse if(p.atomIndex(kept.items,atom)!=null) "duplicate" else null; if(failure) |message| problem.diagnostics.line("warning: {s} {s}: {s}",.{if(goal) "goal" else "init",atom.notation(),message}) else p.append(p.Atom,&kept,atom); } if(goal) problem.goals=kept.items else problem.initial=kept.items; }
}
fn numberList(set:g.Set) []const u8 { var out:p.Text=.{}; for(g.members(set),0..) |q,i| { if(i>0) out.put(",",.{}); out.put("{d}",.{q}); } return if(set==0) "-" else out.data.items; }
fn groundingReport(domain:p.Domain,problem:p.Problem,ground:g.Ground,text:*p.Text) void {
    text.line("",.{}); text.line("== problem {s} ==",.{problem.name}); text.put("{s}",.{problem.diagnostics.data.items}); text.line("objects: {d}",.{problem.objects.len});
    for(domain.types) |typ| { text.put("  {s}:",.{typ.name}); var count:usize=0; for(problem.objects) |object| if(g.subtype(domain,object.typ,typ.name)) { text.put(" {s}",.{object.name}); count+=1; }; if(count==0) text.put(" -",.{}); text.put("\n",.{}); }
